private static int findDelimiter(String input, int from, String needle) {
    int n = input.length();
    int i = from;
    while (i < n) {
        char c = input.charAt(i);
        if (c == '\\') {
            i += 1;
            if (i < n) i += Character.charCount(input.codePointAt(i));
            continue;
        }
        switch (needle) {
            case "**": {
                if (c == '*') {
                    int end = i;
                    while (end < n && input.charAt(end) == '*') end++;
                    if (end - i >= 2) return end - 2;
                }
                break;
            }
            case "*": {
                if (c == '*') {
                    int end = i;
                    while (end < n && input.charAt(end) == '*') end++;
                    if (end - i == 1) return i;
                    i = end;
                    continue;
                }
                break;
            }
            case "__": {
                if (c == '_') {
                    int end = i;
                    while (end < n && input.charAt(end) == '_') end++;
                    if (end - i >= 2 && underscoreCanClose(input, end)) return end - 2;
                }
                break;
            }
            case "_": {
                if (c == '_') {
                    int end = i;
                    while (end < n && input.charAt(end) == '_') end++;
                    if (end - i == 1 && underscoreCanClose(input, end)) return i;
                    i = end;
                    continue;
                }
                break;
            }
            case "~~": {
                if (c == '~') {
                    int end = i;
                    while (end < n && input.charAt(end) == '~') end++;
                    if (end - i >= 2) return end - 2;
                }
                break;
            }
            default: {
                if (input.startsWith(needle, i)) return i;
            }
        }
        i += Character.charCount(input.codePointAt(i));
    }
    return -1;
}
```

